<?php
require_once __DIR__ . '/../config/config.php'; require_staff(); require_csrf();
$id=(int)($_POST['id']??0);$data=[$_POST['blotter_no']??'',$_POST['reporting_person']??'',$_POST['reporting_address']??'',$_POST['incident_type']??'',$_POST['report_datetime']??null,$_POST['incident_datetime']??null,$_POST['place_of_incident']??'',$_POST['narrative']??''];
if($id){$s=$conn->prepare('SELECT barangay_id FROM blotter_records WHERE id=?');$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();if(!$row || ($_SESSION['role']!=='admin' && $row['barangay_id']!=$_SESSION['barangay_id']))die('Access denied.');$s=$conn->prepare('UPDATE blotter_records SET blotter_no=?,reporting_person=?,reporting_address=?,incident_type=?,report_datetime=?,incident_datetime=?,place_of_incident=?,narrative=? WHERE id=?');$s->bind_param('ssssssssi',$data[0],$data[1],$data[2],$data[3],$data[4],$data[5],$data[6],$data[7],$id);$s->execute();}else{$bid=(int)$_SESSION['barangay_id'];$s=$conn->prepare('INSERT INTO blotter_records(barangay_id,blotter_no,reporting_person,reporting_address,incident_type,report_datetime,incident_datetime,place_of_incident,narrative,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->bind_param('isssssssss',$bid,$data[0],$data[1],$data[2],$data[3],$data[4],$data[5],$data[6],$data[7],$_SESSION['full_name']);$s->execute();$id=$conn->insert_id;}redirect(url('pages/incident_report.php?id='.$id));

